EXPECTED_TRANSFERRED_SIGNATURES = {'claim_update': "(self, *, update_id: 'int', telegram_user_id: 'int | None', update_type: 'str', payload_digest: 'str') -> 'bool'", 'store_update_responses': "(self, *, update_id: 'int', responses: 'list[tuple]') -> 'None'", 'pending_update_responses': "(self, update_id: 'int') -> 'list[tuple[int, int, str, dict[str, Any] | None]]'", 'mark_update_response_delivered': "(self, *, update_id: 'int', response_index: 'int') -> 'None'", 'mark_update_processed': "(self, update_id: 'int') -> 'None'", 'retry_update_response': "(self, *, update_id: 'int', response_index: 'int') -> 'None'", 'get_subscription_message_receipt': "(self, telegram_user_id: 'int') -> 'TelegramSubscriptionMessageReceipt | None'", 'record_subscription_message_delivery': "(self, *, telegram_user_id: 'int', token_digest: 'str', chat_id: 'int', message_id: 'int') -> 'None'"}


def test_telegram_registry_public_methods_are_stable():
    actual = [name for name in vars(TelegramRegistry) if not name.startswith("__")]
    assert actual == EXPECTED_TELEGRAM_REGISTRY_NAMES


def test_transferred_method_signatures_are_stable():
    for name, expected in EXPECTED_TRANSFERRED_SIGNATURES.items():
        assert str(inspect.signature(getattr(TelegramRegistry, name))) == expected
